package com.vandorlabs.neoforge.ramp;
import com.vandorlabs.neoforge.NativePlatformComponents;
import com.vandorlabs.neoforge.redstone.*;
import com.vandorlabs.redstone.ChannelList;
import net.minecraft.core.*;
import net.minecraft.nbt.*;
import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.block.entity.*;
import net.minecraft.world.level.block.state.BlockState;
/** Inactive settings/loaded-input foundation. Captured platforms and unfinished recovery stay sealed. */
public class NativeRampEntity extends BlockEntity implements NativeChannelMember {
 public record Visual(NativeRampSettings settings,boolean slab,boolean inert,int receivedPower,int physicalPower){}
 private final boolean slab;private CompoundTag retained=new CompoundTag();private NativeRampSettings settings=NativeRampSettings.defaults();private boolean inert;private int received,physical;private volatile Visual visual;private NativeRampReservations.View reservationView;
 public NativeRampEntity(BlockEntityType<?> type,BlockPos pos,BlockState state,boolean slab){super(type,pos,state);this.slab=slab;retained.putString("Status","Retracted");retained.putInt("Duration",60);retained.putInt("Length",1);retained.putInt("Facing",2);publish();}
 public final NativeRampSettings settings(){return settings;}public final Visual visual(){return visual;}public final boolean inert(){return inert;}public final boolean slab(){return slab;}
 public static final String PLACEMENT_RECOVERY="NativeRampPlacementRecovery",ITEM_RECOVERY="RampRecoverySnapshot";
 private net.minecraft.world.item.ItemStack recoveryDrop=net.minecraft.world.item.ItemStack.EMPTY;
 final void prepareRecoveryDrop(net.minecraft.world.item.ItemStack stack){if(!(level instanceof ServerLevel server)||!server.getServer().isSameThread())throw new IllegalStateException("Ramp recovery drop authority");recoveryDrop=stack.copy();}
 final net.minecraft.world.item.ItemStack takeRecoveryDrop(){var result=recoveryDrop;recoveryDrop=net.minecraft.world.item.ItemStack.EMPTY;return result;}
 /** Configured items carry choices only, never a journal, reservation or location authorization. */
 public final CompoundTag itemSettings(){if(inert)throw new IllegalStateException("Inert Ramp has no ordinary item choices");return settings.itemChoices(horizontalFacing().get3DDataValue());}
 public final CompoundTag recoverySnapshot(){if(!inert)throw new IllegalStateException("Healthy Ramp has no recovery snapshot");return retained.copy();}
 private void requirePlacementMutation(){
  if(!(level instanceof ServerLevel server)||!server.getServer().isSameThread()||isRemoved()||!com.vandorlabs.neoforge.placement.NativeStationaryPlacement.mutating(level,worldPosition))throw new IllegalStateException("Ramp item installation outside placement");
  var chunk=server.getChunkSource().getChunkNow(worldPosition.getX()>>4,worldPosition.getZ()>>4);
  if(chunk==null||chunk.getBlockEntities().get(worldPosition)!=this)throw new IllegalStateException("Ramp item installation on replaced owner");
 }
 public final void installItemChoices(NativeRampSettings next){requirePlacementMutation();if(inert)throw new IllegalStateException("Inert Ramp item installation");settings=java.util.Objects.requireNonNull(next);received=physical=0;reservationView=null;publish();setChanged();queueInputRefresh();}
 public final void installItemSnapshot(CompoundTag prepared,HolderLookup.Provider registries){requirePlacementMutation();if(inert)throw new IllegalStateException("Inert Ramp item installation");loadWithComponents(prepared.copy(),registries);if(inert)throw new IllegalArgumentException("Prepared Ramp item failed installation");received=physical=0;reservationView=null;publish();setChanged();queueInputRefresh();}
 public final void retainPlacementRecovery(CompoundTag prepared){requirePlacementMutation();NativeRampAuthorization.revoke(this);retained=java.util.Objects.requireNonNull(prepared).copy();retained.putBoolean(PLACEMENT_RECOVERY,true);inert=true;settings=NativeRampSettings.defaults();received=physical=0;reservationView=null;NativeRedstoneChannels.unregister(this);publish();setChanged();}
 public final net.minecraft.core.Direction horizontalFacing(){return getBlockState().hasProperty(NativeRampBlock.FACING)?getBlockState().getValue(NativeRampBlock.FACING):net.minecraft.core.Direction.NORTH;}
 public final net.minecraft.core.Direction scanFacing(){return getBlockState().getBlock() instanceof NativeRampBlock?NativeRampBlock.scanFacing(getBlockState()):horizontalFacing();}
 public final NativeRampReservations.View reservationView(){return reservationView;}
 void installReservations(NativeRampReservations.View next){if(!authority())throw new IllegalStateException("Ramp reservation authority");reservationView=next;NativeRampReservations.changed((ServerLevel)level,worldPosition);}
 void copiedChannelFooter(ChannelList next){if(!authority())throw new IllegalStateException("Ramp channel footer authority");settings=NativeRampConfiguration.withChannels(settings,java.util.Objects.requireNonNull(next));publish();setChanged();NativeRedstoneChannels.channelsChanged(this);}
 private void publish(){visual=new Visual(settings,slab,inert,received,physical);}
 private static void emptyList(CompoundTag tag,String key){if(tag.contains(key)&&(!tag.contains(key,Tag.TAG_LIST)||!tag.getList(key,Tag.TAG_COMPOUND).isEmpty()||((ListTag)tag.get(key)).size()!=0))throw new IllegalArgumentException("Deferred Ramp platform ownership "+key);}
 private static void requireSettingsOnly(CompoundTag tag){if(tag.contains(PLACEMENT_RECOVERY)||tag.contains(ITEM_RECOVERY))throw new IllegalArgumentException("Retained Ramp recovery ownership");if(tag.contains("NativeRampSchema")&&(!tag.contains("NativeRampSchema",Tag.TAG_INT)||tag.getInt("NativeRampSchema")!=1))throw new IllegalArgumentException("Future native Ramp schema");if(tag.contains("ControllerVersion")&&(!tag.contains("ControllerVersion",Tag.TAG_INT)||tag.getInt("ControllerVersion")>com.vandorlabs.persistence.SaveSchema.Ramp.CONTROLLER_VERSION))throw new IllegalArgumentException("Future Ramp schema");for(String key:new String[]{"Sources","Cells","RampSourceTiles","RampCanopyBlockers"})emptyList(tag,key);for(String key:new String[]{"Moving","Open","RecoveryPending","RampCanopyWaiting","RampCanopyCommand","VehicleRampFrozen","RampAnalogDeployment","EscalatorRunning","EscalatorRequested"})if(tag.getBoolean(key))throw new IllegalArgumentException("Deferred Ramp runtime "+key);if(tag.contains("OriginalState")&&!"minecraft:air".equals(tag.getString("OriginalState")))throw new IllegalArgumentException("Deferred Ramp original block");if(tag.contains("Original")){if(!tag.contains("Original",Tag.TAG_COMPOUND))throw new IllegalArgumentException("Deferred Ramp original state");var original=tag.getCompound("Original");if(!original.isEmpty()&&(!"minecraft:air".equals(original.getString("Name"))||original.getAllKeys().stream().anyMatch(key->!key.equals("Name")&&!key.equals("Properties"))||original.contains("Properties")&&(!original.contains("Properties",Tag.TAG_COMPOUND)||!original.getCompound("Properties").isEmpty())))throw new IllegalArgumentException("Unknown original AIR payload");}if(tag.contains("ForgeCaps")&&(!tag.contains("ForgeCaps",Tag.TAG_COMPOUND)||!tag.getCompound("ForgeCaps").isEmpty()))throw new IllegalArgumentException("Opaque external capabilities");if(tag.contains("ForgeData")&&!tag.contains("ForgeData",Tag.TAG_COMPOUND))throw new IllegalArgumentException("Unknown saved metadata envelope");if(tag.contains("TransmitterSchema"))throw new IllegalArgumentException("Deferred transmitter schema");var forge=tag.getCompound("ForgeData");for(String key:new String[]{"VandorTransmitters","VandorSharedScreenTransmitter"})if(forge.contains(key)&&(!forge.contains(key,Tag.TAG_COMPOUND)||!forge.getCompound(key).isEmpty()))throw new IllegalArgumentException("Deferred owned transmitter");}
 @Override protected void loadAdditional(CompoundTag input,HolderLookup.Provider registries){NativeRampAuthorization.reading(this);var original=input.copy();try{requireSettingsOnly(original);NativePlatformComponents.requireSupported(original,registries);var next=NativeRampSettings.read(original);try(var platform=NativePlatformComponents.guardLoad(this)){super.loadAdditional(original.copy(),registries);platform.requireSuccessful();}NativePlatformComponents.forgetLoadedFields(original);settings=next;retained=original;inert=level!=null&&level.isClientSide&&input.getBoolean("NativeRampInert");received=input.getBoolean("ChannelSignal")?15:0;}catch(RuntimeException failure){retained=original;settings=NativeRampSettings.defaults();inert=true;received=0;}physical=0;reservationView=null;publish();if(level instanceof ServerLevel){if(inert)NativeRedstoneChannels.unregister(this);else NativeRedstoneChannels.queueRegistration(this);}}
 @Override protected void saveAdditional(CompoundTag tag,HolderLookup.Provider registries){if(inert){NativePlatformComponents.clearForInertSave(this);tag.merge(retained.copy());return;}tag.merge(retained.copy());settings.writeChoices(tag);tag.putInt("NativeRampSchema",1);tag.putBoolean("ChannelSignal",received>0);super.saveAdditional(tag,registries);}
 @Override public CompoundTag getUpdateTag(HolderLookup.Provider registries){var tag=new CompoundTag();settings.writeChoices(tag);tag.putInt("NativeRampSchema",1);tag.putBoolean("NativeRampInert",inert);tag.putBoolean("ChannelSignal",received>0);return tag;}
 @Override public ClientboundBlockEntityDataPacket getUpdatePacket(){return ClientboundBlockEntityDataPacket.create(this);}
 private boolean authority(){return !inert&&level instanceof ServerLevel server&&server.getServer().isSameThread()&&NativeRedstoneChannels.open(server)&&isChannelMemberActive();}
 @Override public BlockEntity channelBlockEntity(){return this;}@Override public ChannelList getRedstoneChannels(){return inert?ChannelList.EMPTY:settings.channels();}
 @Override public boolean isChannelMemberActive(){return !inert&&NativeChannelMember.super.isChannelMemberActive();}
 public final void queueInputRefresh(){if(level instanceof ServerLevel&&!inert)NativeRedstoneChannels.queueRegistration(this);}
 @Override public void beforeChannelRegistration(){if(!authority())return;NativeRampAuthorization.resumed(this);NativeRampBlock.updateModelState(this,false);int next=NativeLoadedRedstonePower.level(level,worldPosition);if(next!=physical){physical=next;publish();setChanged();}}
 @Override public int localSignalLevel(int channel){return authority()?NativeLoadedRedstonePower.level(level,worldPosition):0;}
 @Override public void setChannelLevel(int value){if(!authority())return;value=Math.max(0,Math.min(15,value));if(value==received)return;received=value;publish();setChanged();}
 @Override public void onLoad(){super.onLoad();NativeRampReservations.add(this);if(level instanceof ServerLevel&&!inert)NativeRedstoneChannels.queueRegistration(this);}
 @Override public void setRemoved(){NativeRampAuthorization.removed(this);NativeRampReservations.remove(this);if(level instanceof ServerLevel)NativeRedstoneChannels.unregister(this);super.setRemoved();}
 @Override public void onChunkUnloaded(){NativeRampAuthorization.unloaded(this);NativeRampReservations.remove(this);if(level instanceof ServerLevel)NativeRedstoneChannels.unregister(this);super.onChunkUnloaded();}
}
